-- ═══════════════════════════════════════════════════════════════════════════
--  Catalog familia 'rame' — rame de aluminiu pt. uşi de mobilier (820, 822, 824,
--  831, 841, 842). GENERAT din formularele de comandă ale userului:
--    „Rame 820,822,824- Formular comanda 17.09.xlsm" (foaia Sheet4)
--    „Rame 831,841,842- Formular comanda 17.09.xlsm" (foaia coduri)
--  Rama e un produs GATA DIMENSIONAT: codul = model + sufix culoare + H x L
--  rotunjite în sus la mărimile standard (vezi lib/rame/rame.js). Codul şi denumirea
--  sunt EXACT ca în Excel (unele coduri au „X", altele „x" — căutarea în aplicaţie
--  nu ţine cont de asta, dar codul facturat rămâne cel de aici).
-- ═══════════════════════════════════════════════════════════════════════════

DROP TABLE IF EXISTS articol;
CREATE TABLE articol (
  cod      TEXT,
  tip      TEXT NOT NULL,
  finisaj  TEXT,
  lmin     INTEGER,
  lmax     INTEGER,
  denumire TEXT,
  um       TEXT NOT NULL DEFAULT 'buc',
  activ    INTEGER NOT NULL DEFAULT 1
);

